<title>How to make money on YouTube — YouTube Creators</title>
<style>
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{margin:0;background:#fff;color:#0f0f0f;font-family:Arial,Helvetica,sans-serif;font-size:18px;line-height:1.6}
  .topbar{height:68px;position:fixed;z-index:10;left:0;right:0;top:0;background:rgba(255,255,255,.98);border-bottom:1px solid #e8e8e8;display:flex;align-items:center;padding:0 24px;transition:transform .25s}
  .topbar.hidden{transform:translateY(-100%)}
  .brand{display:flex;align-items:center;gap:5px;width:222px;flex:none;text-decoration:none;color:#111}
  .ytmark{width:32px;height:23px;background:#f00;border-radius:6px;position:relative;display:inline-block}
  .ytmark:after{content:"";position:absolute;left:13px;top:6px;border-left:10px solid white;border-top:6px solid transparent;border-bottom:6px solid transparent}
  .brand-name{font-family:Impact,"Arial Narrow",Arial,sans-serif;font-stretch:condensed;font-size:22px;letter-spacing:-1px;white-space:nowrap}
  nav{height:100%;display:flex;align-items:center;gap:62px}
  nav a{font-size:14px;font-weight:600;color:#555;text-decoration:none;white-space:nowrap}
  .search{margin-left:auto;width:34px;height:40px;border:0;background:none;position:relative;cursor:pointer}
  .search:before{content:"";position:absolute;width:11px;height:11px;border:2px solid #222;border-radius:50%;left:9px;top:10px}
  .search:after{content:"";position:absolute;width:8px;height:2px;background:#222;transform:rotate(48deg);left:20px;top:24px}
  main{padding-top:68px}
  .intro{width:840px;height:476px;margin:66px auto 0;text-align:center;border:1px solid #fafafa;padding:0 34px}
  .intro img{width:90px;height:90px;object-fit:contain;margin-top:0}
  h1{font-size:94px;line-height:1.12;letter-spacing:-3px;margin:33px 0 48px;font-weight:700}
  .intro p{font-size:18px;line-height:1.65;margin:0 auto;max-width:650px}
  .partner{max-width:1456px;margin:146px auto 0;display:grid;grid-template-columns:576px 680px;gap:164px;min-height:700px;border:1px solid #fafafa;padding:0 0 40px}
  .partner-copy h2{font-size:46px;line-height:1.2;margin:0 0 30px;font-weight:700;letter-spacing:-1px}
  .partner-copy>p{margin:0 0 28px;font-size:18px;line-height:1.65}
  .partner-visual{padding-top:0;position:relative}
  .video-card{width:680px;height:383px;position:relative;overflow:hidden;background:#fafafa;margin-top:0}
  .video-card>img{width:100%;height:100%;object-fit:cover}
  .play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:66px;height:47px;border-radius:13px;background:#f00;box-shadow:0 1px 6px #5555}
  .play:after{content:"";position:absolute;left:27px;top:12px;border-left:19px solid white;border-top:12px solid transparent;border-bottom:12px solid transparent}
  .caption{position:absolute;bottom:0;left:0;right:0;padding:12px 16px;background:linear-gradient(transparent,#555b);color:white;font-size:20px}
  .accordions{border-top:1px solid #bbb}
  .accordion{border-bottom:1px solid #bbb}
  .acc-head{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:68px;border:0;background:#fff;text-align:left;padding:14px 4px 14px 0;font:inherit;color:#222;cursor:pointer}
  .acc-head .chev{font-size:20px;color:#666;transition:transform .2s;margin-right:5px}
  .accordion.open .chev{transform:rotate(180deg)}
  .acc-content{display:none;padding:0 0 24px;color:#666;line-height:1.62;font-size:18px}
  .accordion.open .acc-content{display:block}
  .acc-content p{margin:0 0 20px}
  .acc-content ul{padding-left:32px;margin:10px 0 24px}
  .acc-content li{padding-left:2px;margin:0 0 16px}
  a.text-link{color:#1967b2;text-decoration:none;font-weight:600}
  a.text-link:hover{text-decoration:underline}
  .text-link:after{content:" ↗";font-size:18px}
  .ways{max-width:1070px;margin:125px auto 0;text-align:center}
  .ways h2,.next h2{font-size:46px;line-height:1.25;margin:0 0 32px;letter-spacing:-1px}
  .ways>p{max-width:630px;margin:0 auto 20px;line-height:1.6}
  .ways .fine{font-size:14px;color:#777;max-width:600px;margin:18px auto 70px}
  .earn-list{border-top:1px solid #aaa;text-align:left}
  .earn-item{border-bottom:1px solid #bbb}
  .earn-head{height:76px;width:100%;border:0;background:#fff;display:flex;align-items:center;text-align:left;gap:24px;padding:0 8px;cursor:pointer;font:inherit;font-size:22px;color:#222}
  .num{width:42px;height:42px;border-radius:50%;background:#f1f1f1;color:#777;display:grid;place-items:center;font-size:14px;font-weight:700;flex:none}
  .earn-item.open .num{background:#c90016;color:white}
  .earn-head .chev{margin-left:auto;margin-right:0;color:#777;font-size:19px;transition:transform .2s}
  .earn-item.open .chev{transform:rotate(180deg)}
  .earn-content{display:none;padding:18px 0 42px}
  .earn-item.open .earn-content{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
  .earn-content img{width:100%;height:290px;object-fit:cover}
  .earn-content p{margin:0 0 20px;line-height:1.65}
  .next{margin:142px auto 0;text-align:center;max-width:700px;padding-bottom:120px}
  .next p{max-width:630px;margin:30px auto}
  .next-links{display:flex;gap:24px;justify-content:center;flex-wrap:wrap}
  .next-links a{color:#1967b2;text-decoration:none}
  .btn{cursor:pointer}
  @media(max-width:1500px){
    .partner{margin-left:8%;margin-right:8%;grid-template-columns:minmax(420px,1fr) minmax(460px,1.1fr);gap:8%}
    .video-card{width:100%;height:auto;aspect-ratio:16/9}
  }
  @media(max-width:900px){
    .topbar{padding:0 14px}.brand{width:auto;margin-right:25px}.brand-name{font-size:18px}nav{gap:18px}nav a{font-size:12px}
    .intro{width:94%;height:auto;min-height:440px;padding-bottom:25px}h1{font-size:56px;letter-spacing:-2px}
    .partner{display:block;margin:80px 6% 0}.partner-copy h2{font-size:34px}.partner-visual{margin-top:28px}
    .ways{margin:90px 6% 0}.earn-item.open .earn-content{grid-template-columns:1fr}
  }
</style>
</head>
<body>
<header class="topbar" id="topbar">
  <a class="brand btn" href="#" aria-label="YouTube Creators home"><span class="ytmark"></span><span class="brand-name">YouTube Creators</span></a>
  <nav>
    <a class="btn" href="#">Welcome, Creators</a>
    <a class="btn" href="#partner">Partner Program</a>
    <a class="btn" href="#ways">How things work⌄</a>
    <a class="btn" href="#next">Top questions</a>
  </nav>
  <button class="search btn" aria-label="Search"></button>
</header>
<main>
  <section class="intro">
    <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/030.svg" width="90" height="90" alt="">
    <h1>How to make money<br>on YouTube</h1>
    <p>When it comes to turning your ideas into income, you’ve got options.<br>From traditional ads to selling merchandise to memberships for your fans, there are a lot of ways to use your channel and videos to make money.</p>
  </section>

  <section class="partner" id="partner">
    <div class="partner-copy">
      <h2>YouTube Partner Program</h2>
      <p>There are so many formats available to make content on YouTube, such as Shorts, live streaming and long-form video, and we want to make sure Creators can get rewarded for making all of them. The YouTube Partner Program lets qualifying Creators tap into different ways to earn revenue, as well as gives access to resources like 1:1 support and the Copyright Match Tool. Creators are building successful businesses of their own with employees and full-fledged operations and are a significant share of the more than $50B we’ve paid out to creators, artists and media companies over the last three years.</p>
      <div class="accordions">
        <div class="accordion">
          <button class="acc-head btn"><span>Are you eligible?</span><span class="chev">⌄</span></button>
          <div class="acc-content">
            <p>To qualify for the YouTube Partner Program, you need to be in good standing with YouTube, follow all the <a class="text-link btn" href="#">YouTube monetization policies</a>, and live in a country/region where <a class="text-link btn" href="#">the YouTube Partner Program is available</a>.</p>
            <p>Creators in <a class="text-link btn" href="#">these countries/regions</a> are now able to qualify for the YouTube Partner Program sooner:</p>
            <ul>
              <li>Apply to the program and unlock benefits like fan funding and select YouTube Shopping features at the following eligibility criteria:
                <ul><li>500 subscribers with 3 public uploads in the last 90 days, and either 3K valid public watch hours in the last 12 months OR 3M public Shorts views in the last 90 days.</li></ul>
              </li>
              <li>Unlock even more benefits including revenue sharing from ads and YouTube Premium when you hit:
                <ul><li>1,000 subscribers and either 4K valid public watch hours in the last 12 months OR 10M valid public Shorts views in the last 90 days.</li></ul>
              </li>
            </ul>
            <p>All creators will go through a standard review process upon applying to ensure their channel meets our policies and guidelines. Some features may have additional eligibility criteria.</p>
            <a class="text-link btn" href="#">Learn more about the YouTube Partner Program</a>
          </div>
        </div>
        <div class="accordion">
          <button class="acc-head btn"><span>The benefits of being in the YouTube Partner Program</span><span class="chev">⌄</span></button>
          <div class="acc-content">
            <p>The YouTube Partner Program is a comprehensive partner program available to Creators, delivering support, monetization opportunities and more. Once you’re in the program, you can start earning money from ads on long-form videos, ads between short-form videos and from YouTube Premium subscribers watching your content. You can also use Shopping to offer products to your audience and access Fan Funding revenue streams including Super Chat, Super Thanks, Super Stickers and channel memberships. What’s more, creators in the program are guaranteed access to our Creator Support team with one-to-one help over email and chat and automatic copyright flags of reuploaded content through the Copyright Match Tool. We’re always exploring ways to make the YouTube Partner Program the most rewarding and supportive experience for our Creators.</p>
            <p><a class="text-link btn" href="#">Read more about how to earn money on YouTube</a></p>
            <p><a class="text-link btn" href="#">Read about the ads algorithm</a></p>
            <p><a class="text-link btn" href="#">Get Creator Tips on the YouTube Partner Program</a></p>
          </div>
        </div>
      </div>
    </div>
    <div class="partner-visual">
      <div class="video-card">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/006.jpg" width="680" height="383" alt="Make money on YouTube Partner Program">
        <span class="play"></span>
        <div class="caption">YouTube Partner Program: How to Make Money on YouTube</div>
      </div>
    </div>
  </section>

  <section class="ways" id="ways">
    <h2>Multiple ways to earn</h2>
    <p>Learn your options for earning money on YouTube, explore what makes the most sense for your channel and start earning.</p>
    <p class="fine">*Subject to terms and conditions, which may be different based on region. Eligibility requirements and territory restrictions apply.</p>
    <div class="earn-list">
      <div class="earn-item open">
        <button class="earn-head btn"><span class="num">01</span><span>Ad revenue &amp; YouTube Premium</span><span class="chev">⌃</span></button>
        <div class="earn-content">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/013.webp" width="520" height="290" alt="How ads work on YouTube">
          <div><p>Earn ad revenue from display, overlay, and video ads that run on your channel. With YouTube Premium, you can earn a portion of a subscriber’s fee when they watch your content.</p><a class="text-link btn" href="#">Get Creator Tips for how ads work</a></div>
        </div>
      </div>
      <div class="earn-item">
        <button class="earn-head btn"><span class="num">02</span><span>Super Chat &amp; Super Stickers</span><span class="chev">⌄</span></button>
        <div class="earn-content"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/012.jpg" width="520" height="290" alt="Super Thanks"><div><p>Build a community and earn money from fans who want to show their support with Super Chat and Super Stickers during live streams and Premieres.</p><a class="text-link btn" href="#">Learn more about fan funding</a></div></div>
      </div>
      <div class="earn-item">
        <button class="earn-head btn"><span class="num">03</span><span>YouTube Shopping</span><span class="chev">⌄</span></button>
        <div class="earn-content"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/009.jpg" width="520" height="290" alt="YouTube Shopping"><div><p>Showcase your products and connect your store to YouTube Shopping, making it easy for viewers to discover and buy from you.</p><a class="text-link btn" href="#">Explore YouTube Shopping</a></div></div>
      </div>
      <div class="earn-item">
        <button class="earn-head btn"><span class="num">04</span><span>Channel Memberships</span><span class="chev">⌄</span></button>
        <div class="earn-content"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/004.svg" width="520" height="290" alt="Creator award"><div><p>Offer channel memberships and give your biggest fans access to exclusive perks, content and community benefits.</p><a class="text-link btn" href="#">Learn about channel memberships</a></div></div>
      </div>
      <div class="earn-item">
        <button class="earn-head btn"><span class="num">05</span><span>YouTube BrandConnect</span><span class="chev">⌄</span></button>
        <div class="earn-content"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/027.svg" width="520" height="290" alt="Creators working together"><div><p>Connect with brands and find opportunities to create branded content that works for you and your audience.</p><a class="text-link btn" href="#">Discover YouTube BrandConnect</a></div></div>
      </div>
      <div class="earn-item">
        <button class="earn-head btn"><span class="num">06</span><span>Super Thanks</span><span class="chev">⌄</span></button>
        <div class="earn-content"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/012.jpg" width="520" height="290" alt="Super Thanks"><div><p>With Super Thanks, viewers can show extra appreciation on your videos while you earn revenue from their support.</p><a class="text-link btn" href="#">Learn more about Super Thanks</a></div></div>
      </div>
    </div>
  </section>

  <section class="next" id="next">
    <h2>What’s next?</h2>
    <p>Curious to learn more? Keep exploring the tools and tips that will help keep your channel growing, plus the guidelines that protect and empower Creators.</p>
    <div class="next-links"><a class="btn" href="#">Creator tools</a><a class="btn" href="#">Tips for your channel</a><a class="btn" href="#">Policies and guidelines</a></div>
  </section>
</main>
<script>
  document.querySelectorAll('.acc-head').forEach(button=>{
    button.addEventListener('click',()=>{
      const parent=button.parentElement;
      parent.classList.toggle('open');
    });
  });
  document.querySelectorAll('.earn-head').forEach(button=>{
    button.addEventListener('click',()=>{
      const item=button.parentElement;
      const wasOpen=item.classList.contains('open');
      document.querySelectorAll('.earn-item').forEach(other=>other.classList.remove('open'));
      if(!wasOpen)item.classList.add('open');
    });
  });
  let previous=window.scrollY;
  window.addEventListener('scroll',()=>{
    const current=window.scrollY;
    const bar=document.getElementById('topbar');
    if(current>1250 && current>previous+3) bar.classList.add('hidden');
    else if(current<previous-3 || current<1250) bar.classList.remove('hidden');
    previous=current;
  },{passive:true});
</script>
</body>
</html>
